CREATE PROCEDURE [dbo].[SP_Save_CashRefund] 
	-- Add the parameters for the stored procedure here
    @XMLDetails AS XML ,
    @docID VARCHAR(MAX) OUTPUT ,
    @Recipientheaderid INT OUTPUT
AS
    DECLARE @iDocID INT 

    BEGIN TRY
        BEGIN TRANSACTION

        EXEC sp_xml_preparedocument @iDocID OUTPUT, @XMLDetails;

        IF OBJECT_ID('tempdb.dbo.#TEMPRInvoiceHeader', 'U') IS NOT NULL
            DROP TABLE #TEMPRInvoiceHeader;
			
        IF OBJECT_ID('tempdb.dbo.#TEMPInvoiceDetail', 'U') IS NOT NULL
            DROP TABLE #TEMPInvoiceDetail; 
			

        SELECT  [InvoiceNo] ,
                [CustomerID] ,
                [InvoiceDate] ,
                [DepartmentID] ,
                [Location] ,
                [TotalDiscount] ,
                [ToatlDiscountRate] ,
                [ItemDiscountTotal] ,
                [TaxTotal] ,
                [OtherCharges] ,
                GETDATE() AS [sysDate] ,
                [UserID] ,
                [IPAddress] ,
                [CreatedUserID] ,
                [LastModUserID] ,
                [CreatedDate] ,
                [LastModDate] ,
                [CustomerName] ,
                [PropertyID] ,
                [VATNo] ,
                [SalesPersonID] ,
                [TotalPrintDiscount] ,
                [SubTotal] ,
                [IsSerialUpdated] ,
                [IsPercentageForDiscount] ,
                [GrossTotal] ,
                [NetTotal] ,
                [ItemDiscountType],
				[ReferenceNo]
        INTO    #TEMPRInvoiceHeader
        FROM    OPENXML(@iDocID, 'CashRefundViewModel/Invoiceheader', 2)
    WITH
    (
        [InvoiceNo]VARCHAR(MAX), 
        [CustomerID] INT,
        [InvoiceDate] DATETIME,
        [DepartmentID] INT,
        [Location] INT,       
        [TotalDiscount] DECIMAL(18, 2),       
        [ToatlDiscountRate] DECIMAL(18, 2),
        [ItemDiscountTotal] DECIMAL(18, 2),
        [TaxTotal] DECIMAL(18, 2),
        [OtherCharges] DECIMAL(18, 2),
        [sysDate] DATETIME,
        [UserID] INT,
        [IPAddress] NVARCHAR(MAX),
        [CreatedUserID] INT,
        [LastModUserID] INT,
        [CreatedDate] DATETIME,
        [LastModDate] DATETIME,
		[CustomerName] NVARCHAR(MAX),
		[PropertyID] INT,
	    [VATNo]	INT,
		[SalesPersonID] INT,
		[TotalPrintDiscount] DECIMAL(18,2),
		[SubTotal] DECIMAL(18, 2),
		[IsSerialUpdated] BIT,
		[IsPercentageForDiscount] BIT,
		[GrossTotal] DECIMAL(18, 2),
		[NetTotal] DECIMAL(18, 2),
		[ItemDiscountType] INT,
		[ReferenceNo] NVARCHAR(MAX)


    );


        IF OBJECT_ID('tempdb.dbo.#TEMPRInvoiceDetail', 'U') IS NOT NULL
            DROP TABLE #TEMPRInvoiceDetail; 

        EXEC sp_xml_preparedocument @iDocID OUTPUT, @XMLDetails;
        SELECT  [ID],[ItemID] ,
                [QTY] ,
                [UnitID] ,
                [UnitPrice] ,
                [DelievryQTY] ,
                [ReturnQty] ,
                [AveragePrice] ,
                [CostPrice] ,
                [TaxGroupID] ,
                [TaxValue] ,
                [SerialNo] ,
                [ItemDiscountValue] ,
                [ItemDiscountType] ,
                [IPAddress] ,
                [CreatedUserID] ,
                [LastModUserID] ,
                [CreatedDate] ,
                [LastModDate] ,
                [ItemDiscountPercentage] ,
                [WarrentyPeriod] ,
                [IsPercentageForDiscount] ,
                [TaxCostPrice] ,
                [TaxForSellPrice] ,
                [PrintSequence] ,
                [TaxInclusivePrice]
        INTO    #TEMPRInvoiceDetail
        FROM    OPENXML(@iDocID, 'CashRefundViewModel/InvoiceDetails/InvoiceDetailViewModel', 2)

		
    WITH
    (   [ID] INT,
        [ItemID] INT,
        [QTY] DECIMAL(18, 2),
        [UnitID] INT,
        [UnitPrice] DECIMAL(18, 2),
        [DelievryQTY] DECIMAL(18, 2),
        [ReturnQty] DECIMAL(18, 2),
        [AveragePrice] DECIMAL(18, 2),
        [CostPrice] DECIMAL(18, 2),
        [TaxGroupID] INT,
        [TaxValue] DECIMAL(18, 2),
        [SerialNo] NVARCHAR(MAX),
        [ItemDiscountValue] DECIMAL(18, 2),
        [ItemDiscountType] INT,      
        [IPAddress] NVARCHAR(MAX),
        [CreatedUserID] INT,
        [LastModUserID] INT,
        [CreatedDate] DATETIME,
        [LastModDate] DATETIME,
		[ItemDiscountPercentage] DECIMAL(18, 2),
	    [WarrentyPeriod] DECIMAL(18, 2),
	    [IsPercentageForDiscount] BIT ,
		[TaxCostPrice] DECIMAL(18,2),
		[TaxForSellPrice] DECIMAL(18,2),
		[PrintSequence] DECIMAL(18,2),
	    [TaxInclusivePrice] DECIMAL(18,2)
    );

        IF OBJECT_ID('tempdb.dbo.#TEMPRInvoicePaymentsDetails', 'U') IS NOT NULL
            DROP TABLE #TEMPRInvoicePaymentsDetails;

        SELECT  [ID] ,
                [InvoiceHeaderID] ,
                [PaymentTypeID] ,
                [TenderedAmount] ,
                [ActualAmount] ,
                [BalanceAmount] ,
                [Remarks] ,
                [ReferanceNumebrs] ,
                [IPAddress] ,
                [CreatedUserID] ,
                [LastModUserID] ,
                [CreatedDate] ,
                [LastModDate] ,
                [CheckNumber] ,
                [BankId] ,
                [BranchId] ,
                [CreditNumber] ,
                [CnId]
        INTO    #TEMPRInvoicePaymentsDetails
        FROM    OPENXML(@iDocID, 'CashRefundViewModel/PaymentDetails/PaymentsDetailsViewModel', 2) 
    WITH
    (   [ID] INT,
        [InvoiceHeaderID] INT,
        [PaymentTypeID] INT,
        [TenderedAmount] DECIMAL(18, 2),
        [ActualAmount] DECIMAL(18, 2),
        [BalanceAmount] DECIMAL(18, 2),
        [Remarks] NVARCHAR(MAX),
        [ReferanceNumebrs] NVARCHAR(MAX),
        [IPAddress] NVARCHAR(MAX),
        [CreatedUserID] INT,
        [LastModUserID] INT,
        [CreatedDate] DATETIME,
        [LastModDate] DATETIME,
		[CheckNumber] INT,
		[BankId] INT,
		[BranchId] INT,		
		[CreditNumber] NVARCHAR(MAX),
		[CnId] INT
    );

        DECLARE @DocumentNo VARCHAR(MAX) ,
            @PrefixRnd VARCHAR(2)= 'RC' ,
            @DepartmentID INT ,
            @PropertyID INT ,
            @LocationID INT ,
            @StockTransactionHeaderID INT ,
            @CreatedUserID INT ,
            @Total DECIMAL(18, 2)  
        SELECT  @DepartmentID = DepartmentID ,
                @PropertyID = PropertyID ,
                @LocationID = Location ,
                @CreatedUserID = CreatedUserID ,
                @Total = NetTotal
        FROM    #TEMPRInvoiceHeader


        SELECT  @DocumentNo = dbo.FN_GetNextDocumentNumberForInvoice(@DepartmentID,
                                                              @PrefixRnd)

        IF @DocumentNo IS NULL
            BEGIN
	
                INSERT  INTO dbo.InvoiceWiseNextNumbers
                        ( DepartmentId ,
                          Prefix ,
                          NextNo ,
                          LengthOfFormatting
	                    )
                VALUES  ( @DepartmentID , -- DepartmentId - int
                          'RC' , -- Prefix - varchar(2)
                          1 , -- NextNo - int
                          6  -- LengthOfFormatting - int
	                    )
            END



        SELECT  @DocumentNo = dbo.FN_GetNextDocumentNumberForInvoice(@DepartmentID,
                                                              @PrefixRnd)


        UPDATE  InvoiceWiseNextNumbers
        SET     NextNo = NextNo + 1
        WHERE   DepartmentId = @DepartmentID
                AND Prefix = @PrefixRnd

        INSERT  INTO dbo.InvoiceHeaders
                ( InvoiceNo ,
                  CustomerID ,
                  InvoiceDate ,
                  InvoiceMode ,
                  DepartmentID ,
                  Location ,
                  TotalDiscount ,
                  ItemDiscountTotal ,
                  TaxTotal ,
                  OtherCharges ,
                  sysDate ,
                  UserID ,
                  IPAddress ,
                  CreatedUserID ,
                  LastModUserID ,
                  CreatedDate ,
                  LastModDate ,
                  CustomerName ,
                  PropertyID ,
                  VATNo ,
                  SalesPersonID ,
                  TotalPrintDiscount ,
                  SubTotal ,
                  IsSerialUpdated ,
                  IsPercentageForDiscount ,
                  ToatlDiscountRate ,
                  GrossTotal ,
                  NetTotal ,
                  ItemDiscountType ,
                  Isprint,
				  ReferenceNo
		        )
                SELECT  @DocumentNo ,
                        CustomerID ,
                        InvoiceDate ,
                        2 ,
                        DepartmentID ,
                        Location ,
                        TotalDiscount ,
                        ItemDiscountTotal ,
                        TaxTotal ,
                        OtherCharges ,
                        sysDate ,
                        UserID ,
                        IPAddress ,
                        CreatedUserID ,
                        LastModUserID ,
                        CreatedDate ,
                        LastModDate ,
                        CustomerName ,
                        PropertyID ,
                        VATNo ,
                        SalesPersonID ,
                        TotalPrintDiscount ,
                        SubTotal ,
                        IsSerialUpdated ,
                        IsPercentageForDiscount ,
                        ToatlDiscountRate ,
                        GrossTotal ,
                        NetTotal ,
                        ItemDiscountType ,
                        0,
						ReferenceNo
                FROM    #TEMPRInvoiceHeader

        SELECT  @Recipientheaderid = SCOPE_IDENTITY()

        SELECT  @docID = @DocumentNo


        INSERT  INTO dbo.InvoiceDetails
                ( InvoiceHeaderID ,
                  ItemID ,
                  QTY ,
                  UnitID ,
                  UnitPrice ,
                  DelievryQTY ,
                  ReturnQty ,
                  AveragePrice ,
                  CostPrice ,
                  TaxGroupID ,
                  TaxValue ,
                  SerialNo ,
                  ItemDiscountValue ,
                  ItemDiscountType ,
                  IPAddress ,
                  CreatedUserID ,
                  LastModUserID ,
                  CreatedDate ,
                  LastModDate ,
                  ItemDiscountPercentage ,
                  WarrentyPeriod ,
                  IsPercentageForDiscount ,
                  TaxCostPrice ,
                  TaxForSellPrice ,
                  PrintSequence
				 )
                SELECT  @Recipientheaderid ,
                        ItemID ,
                        QTY ,
                        UnitID ,
                        UnitPrice ,
                        0 ,
                        0 ,
                        AveragePrice ,
                        CostPrice ,
                        TaxGroupID ,
                        TaxValue ,
                        SerialNo ,
                        ItemDiscountValue ,
                        ItemDiscountType ,
                        IPAddress ,
                        CreatedUserID ,
                        LastModUserID ,
                        CreatedDate ,
                        LastModDate ,
                        ItemDiscountPercentage ,
                        WarrentyPeriod ,
                        IsPercentageForDiscount ,
                        TaxCostPrice ,
                        TaxForSellPrice ,
                        PrintSequence
                FROM    #TEMPRInvoiceDetail




      --for updating stocktransactionheaders and details

	    



        IF NOT EXISTS ( SELECT  *
                        FROM    dbo.StockTransactionHeaders
                        WHERE   CONVERT(VARCHAR, TransactionDate, 101) = CONVERT(VARCHAR, GETDATE(), 101)
                                AND TransactionType = 'RC'
                                AND PropertyID = @PropertyID )
            BEGIN

                  
                DECLARE @DocNoTransaction VARCHAR(MAX)

                SELECT  @DocNoTransaction = dbo.FN_GetNextDocumentNumber(@PropertyID,
                                                              @LocationID,
                                                              'RC')
                       
                IF @DocNoTransaction IS NULL
                    BEGIN
                        INSERT  INTO TransactionTypeWiseNextNumbers
                                ( PropertyID ,
                                  LocationID ,
                                  TransactionType ,
                                  NextNumber ,
                                  LengthOfFormatting
                                )
                        VALUES  ( @PropertyID ,
                                  @LocationID ,
                                  'RC' ,
                                  1 ,
                                  6
                                )
                    END



                SELECT  @DocNoTransaction = dbo.FN_GetNextDocumentNumber(@PropertyID,
                                                              @LocationID,
                                                              'RC')


 
                DECLARE @Prefix VARCHAR(MAX) ,
                    @Len INT ,
                    @Code VARCHAR(MAX) 


                SELECT  @Prefix = Prefix
                FROM    dbo.Locations
                WHERE   Id = @LocationID                      


                SELECT  LEN(@Prefix)

                SELECT  @Prefix = SUBSTRING(@Prefix, 1, 3)

                SET @DocNoTransaction = @Prefix + '/' + @DocNoTransaction


				


                UPDATE  TransactionTypeWiseNextNumbers
                SET     NextNumber = NextNumber + 1
                WHERE   LocationID = @LocationID
                        AND TransactionType = 'RC'		




                INSERT  INTO dbo.StockTransactionHeaders
                        ( DocumentNo ,
                          TransactionType ,
                          TransactionDate ,
                          PropertyID ,
                          LocationID ,
                          ReferenceNo ,
                          SupplierID ,
                          Remarks ,
                          ReferenceID ,
                          DepartmentID ,
                          UserProfileID ,
                          TransferLocationID ,
                          TimeStamp ,
                          TransactionID ,
                          Mode ,
                          SuppCurrencyID ,
                          ExchangeRate ,
                          IPAddress ,
                          CreatedUserID ,
                          LastModUserID ,
                          CreatedDate ,
                          LastModDate ,
                          IsPrint ,
                          IsApproved
		                )
                VALUES  ( @DocNoTransaction ,       -- DocumentNo - nvarchar(20)
                          'RC' ,       -- TransactionType - nvarchar(2)
                          GETDATE() , -- TransactionDate - datetime
                          @PropertyID ,         -- PropertyID - int
                          @LocationID ,         -- LocationID - int
                          N'' ,       -- ReferenceNo - nvarchar(20)
                          0 ,         -- SupplierID - int
                          N'' ,       -- Remarks - nvarchar(20)
                          0 ,         -- ReferenceID - int
                          @DepartmentID ,         -- DepartmentID - int
                          @CreatedUserID ,         -- UserProfileID - int
                          0 ,         -- TransferLocationID - int
                          N'' ,       -- TimeStamp - nvarchar(256)
                          0 ,         -- TransactionID - int
                          N'' ,       -- Mode - nvarchar(1)
                          0 ,         -- SuppCurrencyID - int
                          0 ,      -- ExchangeRate - decimal(18, 2)
                          N'' ,       -- IPAddress - nvarchar(max)
                          @CreatedUserID ,         -- CreatedUserID - int
                          @CreatedUserID ,         -- LastModUserID - int
                          GETDATE() , -- CreatedDate - datetime
                          GETDATE() , -- LastModDate - datetime
                          0 ,      -- IsPrint - bit
                          0       -- IsApproved - bit
			            )
                SELECT  @StockTransactionHeaderID = SCOPE_IDENTITY()
            END 
        ELSE
            BEGIN
                SELECT  @StockTransactionHeaderID = Id
                FROM    dbo.StockTransactionHeaders
                WHERE   CONVERT(VARCHAR, TransactionDate, 101) = CONVERT(VARCHAR, GETDATE(), 101)
                        AND TransactionType = 'RC'
                        AND PropertyID = @PropertyID
            END

        SELECT  *
        INTO    #TEMPInvoiceDetail
        FROM    dbo.InvoiceDetails
        WHERE   InvoiceHeaderID = @Recipientheaderid 

        SELECT  *
        FROM    #TEMPInvoiceDetail

        DECLARE @TempInvoiceDetailId INT ,
            @TempItemId INT ,
            @TempQty DECIMAL ,
            @TempunitID INT ,
            @TempAveragePrice DECIMAL 
        WHILE ( SELECT  COUNT(*)
                FROM    #TEMPInvoiceDetail
              ) > 0
            BEGIN
                SELECT TOP 1
                        @TempInvoiceDetailId = ID ,
                        @TempItemId = ItemID ,
                        @TempQty = QTY ,
                        @TempunitID = UnitID ,
                        @TempAveragePrice = AveragePrice
                FROM    #TEMPInvoiceDetail
                ORDER BY ID 
	
                IF NOT EXISTS ( SELECT  *
                                FROM    dbo.StockTransactionDetails
                                WHERE   CONVERT(VARCHAR, CreatedDate, 101) = CONVERT(VARCHAR, GETDATE(), 101)
                                        AND StockItemID = @TempItemId
                                        AND StockTransactionHeaderID = @StockTransactionHeaderID )
                    BEGIN   
                        INSERT  INTO dbo.StockTransactionDetails
                                ( StockTransactionHeaderID ,
                                  StockItemID ,
                                  Quantity ,
                                  UnitPrice ,
                                  TxnUnitID ,
                                  MasterUnitID ,
                                  MasterUnitConversion ,
                                  ReportUnitID ,
                                  ReportUnitConversion ,
                                  DiscountValue ,
                                  DiscountPercentage ,
                                  TimeStamp ,
                                  StockMasterQuantity ,
                                  StockMasterAveragePrice ,
                                  NewQuantity ,
                                  NewAveragePrice ,
                                  Remarks ,
                                  UserProfileId ,
                                  CostTransactionAccountID ,
                                  PurchaseTransactionAccountID ,
                                  TxnType ,
                                  BalanceQuantity ,
                                  ReturnQuantity ,
                                  ItemUnitPriceInSuppCurrency ,
                                  IPAddress ,
                                  CreatedUserID ,
                                  LastModUserID ,
                                  CreatedDate ,
                                  LastModDate
				                )
                                SELECT  @StockTransactionHeaderID ,
                                        ItemID ,
                                        QTY ,
                                        UnitPrice ,
                                        UnitID ,
                                        ISNULL(dbo.FN_GetMasterUnitID(@PropertyID,
                                                              @LocationID,
                                                              @TempItemId), 0) MasterUnitID ,
                                        ISNULL(dbo.FN_GetUnitConvertionRate(@PropertyID,
                                                              UnitID,
                                                              dbo.FN_GetMasterUnitID(@PropertyID,
                                                              @LocationID,
                                                              @TempItemId)), 0) MasterUnitConversion ,
                                        ISNULL(dbo.FN_GetReportingUnitID(@PropertyID,
                                                              @LocationID,
                                                              @TempItemId), 0) ReportUnitID ,
                                        dbo.FN_GetUnitConvertionRate(@PropertyID,
                                                              UnitID,
                                                              dbo.FN_GetReportingUnitID(@PropertyID,
                                                              @LocationID,
                                                              @TempItemId)) ReportUnitConversion ,
                                        ItemDiscountValue ,
                                        ItemDiscountPercentage ,
                                        '' TimeStamp ,
                                        dbo.FN_GetStockInHand(@PropertyID,
                                                              @LocationID,
                                                              @TempItemId) StockMasterQuantity ,
                                        0 ,
                                        dbo.FN_GetStockInHand(@PropertyID,
                                                              @LocationID,
                                                              @TempItemId)
                                        - QTY ,
                                        0 ,
                                        '' Remarks ,
                                        CreatedUserID ,
                                        dbo.FN_GetPurchaseCostOfSalesAccountID(@TempItemId,
                                                              @LocationID) CostTransactionAccountID ,
                                        dbo.FN_GetPurchaseTransactionAccountID(@TempItemId,
                                                              @LocationID) PurchaseTransactionAccountID ,
                                        'I' ,
                                        0 ,
                                        0 ,
                                        0 ,
                                        IPAddress ,
                                        CreatedUserID ,
                                        CreatedUserID ,
                                        GETDATE() ,
                                        GETDATE()
                                FROM    #TEMPInvoiceDetail
                                WHERE   ID = @TempInvoiceDetailId

                    END 
                ELSE
                    BEGIN
                        UPDATE  StockTransactionDetails
                        SET     Quantity = Quantity + @TempQty
                        WHERE   StockItemID = @TempItemId
                                AND StockTransactionHeaderID = @StockTransactionHeaderID
                                AND CONVERT(VARCHAR, CreatedDate, 101) = CONVERT(VARCHAR, GETDATE(), 101)
                    END 


                        
    
                EXEC [SP_UpdateStockItemBalance] @PropertyID, @LocationID,
                    @TempItemId, 'GR', @TempQty, @TempunitID,
                    @TempAveragePrice
                DELETE  FROM #TEMPInvoiceDetail
                WHERE   ID = @TempInvoiceDetailId
            END 
					
					
					
					SELECT * FROM #TEMPRInvoicePaymentsDetails	           

        DECLARE @PayID INT ,
            @PayAmount DECIMAL(18, 2)

        WHILE ( SELECT  COUNT(*)
                FROM    #TEMPRInvoicePaymentsDetails
              ) > 0 
            BEGIN

	     
                 SELECT TOP ( 1 )
                        @PayID = PDD.ID ,
                        @PayAmount = PDD.ActualAmount
                FROM    #TEMPRInvoicePaymentsDetails PDD
                        INNER JOIN dbo.PaymentTypes PT ON PT.ID = PDD.PaymentTypeID
                ORDER BY PT.sequence


				IF(@PayAmount>=@Total AND @Total <> 0)
				BEGIN
				INSERT INTO dbo.InvoicePaymentsDetails
				        ( InvoiceHeaderID ,
				          PaymentTypeID ,
				          TenderedAmount ,
				          ActualAmount ,
				          BalanceAmount ,
				          Remarks ,
				          ReferanceNumebrs ,
				          IPAddress ,
				          CreatedUserID ,
				          LastModUserID ,
				          CreatedDate ,
				          LastModDate ,
				          CreditNumber ,
				          CreditRequestID
				        )
				VALUES  ( @Recipientheaderid , -- InvoiceHeaderID - int
				          @PayID , -- PaymentTypeID - int
				          @PayAmount , -- TenderedAmount - decimal
				          @Total , -- ActualAmount - decimal
				          0 , -- BalanceAmount - decimal
				          N'' , -- Remarks - nvarchar(max)
				          N'' , -- ReferanceNumebrs - nvarchar(max)
				          N'' , -- IPAddress - nvarchar(max)
				          @CreatedUserID , -- CreatedUserID - int
				          @CreatedUserID , -- LastModUserID - int
				          GETDATE() , -- CreatedDate - datetime
				          GETDATE() , -- LastModDate - datetime
				          N'' , -- CreditNumber - nvarchar(max)
				          0  -- CreditRequestID - int
				        )

						--added on 2019-11-01 to fix balance 

						SELECT @Total=0
				END
                
				ELSE IF(@PayAmount<@Total AND  @Total <> 0)
				BEGIN
				DECLARE @Pay DECIMAL(18,2)

				INSERT INTO dbo.InvoicePaymentsDetails
				        ( InvoiceHeaderID ,
				          PaymentTypeID ,
				          TenderedAmount ,
				          ActualAmount ,
				          BalanceAmount ,
				          Remarks ,
				          ReferanceNumebrs ,
				          IPAddress ,
				          CreatedUserID ,
				          LastModUserID ,
				          CreatedDate ,
				          LastModDate ,
				          CreditNumber ,
				          CreditRequestID
				        )
				VALUES  ( @Recipientheaderid , -- InvoiceHeaderID - int
				          @PayID , -- PaymentTypeID - int
				          @PayAmount , -- TenderedAmount - decimal
				          @PayAmount , -- ActualAmount - decimal
				          0 , -- BalanceAmount - decimal
				          N'' , -- Remarks - nvarchar(max)
				          N'' , -- ReferanceNumebrs - nvarchar(max)
				          N'' , -- IPAddress - nvarchar(max)
				          @CreatedUserID , -- CreatedUserID - int
				          @CreatedUserID , -- LastModUserID - int
				          GETDATE() , -- CreatedDate - datetime
				          GETDATE() , -- LastModDate - datetime
				          N'' , -- CreditNumber - nvarchar(max)
				          0  -- CreditRequestID - int
				        )
				 
				 SELECT @Pay=@PayAmount-@Total

				 SELECT @Total=ABS(@Pay)

				end
                
				SELECT @Total
                DELETE  FROM #TEMPRInvoicePaymentsDetails
                WHERE   ID = @PayID

            END

			DECLARE @PrevHeaderID INT,@UpdateQty DECIMAL(18,2)


			---to update #TEMPRInvoiceDetail
			WHILE(SELECT COUNT(*) FROM #TEMPRInvoiceDetail)>0
			BEGIN
            
			SELECT TOP(1) @PrevHeaderID=ID,@UpdateQty=QTY FROM #TEMPRInvoiceDetail ORDER BY ID

			UPDATE dbo.InvoiceDetails SET ReturnQty=ReturnQty+@UpdateQty WHERE ID=@PrevHeaderID			

			DELETE FROM #TEMPRInvoiceDetail WHERE ID=@PrevHeaderID



			End
      
							
        --SELECT  *
        --FROM    #TEMPRInvoicePaymentsDetails PDD
        --        INNER JOIN dbo.PaymentTypes PT ON PT.ID = PDD.PaymentTypeID
        --ORDER BY PT.[Sequence]


        EXEC sp_xml_removedocument @iDocID
        IF @@TRANCOUNT > 0
            COMMIT TRAN
 
    END TRY
    BEGIN CATCH
        RETURN CAST(ERROR_NUMBER() AS VARCHAR(10)) + ' - ' + ERROR_MESSAGE() + ' - On Line ' + CAST(ERROR_LINE() AS VARCHAR(10))
        IF @@TRANCOUNT > 0
            ROLLBACK TRAN 
    END CATCH

GO

